import{_ as a,o as i,c as o,ag as t}from"./chunks/framework.B_zcDAFh.js";const m=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),l={name:"guide/changelog.md"};function r(n,e,d,s,h,c){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_1-2-48" tabindex="-1">1.2.48 <a class="header-anchor" href="#_1-2-48" aria-label="Permalink to &quot;1.2.48&quot;">​</a></h2><ul><li>Use swing-twist decomposition to fix undesirable rotational drift when twist propagation is enabled.</li><li>Minimum supported Unity version bumped to 2022.3.</li></ul><h2 id="_1-2-47" tabindex="-1">1.2.47 <a class="header-anchor" href="#_1-2-47" aria-label="Permalink to &quot;1.2.47&quot;">​</a></h2><ul><li>Add <code>BoingBehavior.HandleTeleport()</code> and <code>BoingBones.HandleTeleport()</code> to handle teleportation of objects. Call them after teleporting objects to prevent sudden jumps in the bouncy effect.</li><li>Fix materials that sample reactor fields not rendering in edit mode under HDRP in Unity 6.</li></ul><h2 id="_1-2-46" tabindex="-1">1.2.46 <a class="header-anchor" href="#_1-2-46" aria-label="Permalink to &quot;1.2.46&quot;">​</a></h2><ul><li>Add stock URP and HDRP shaders and materials built using shader graphs.</li><li>Null checks when rebooting and rescanning bone chains.</li></ul><h2 id="_1-2-45" tabindex="-1">1.2.45 <a class="header-anchor" href="#_1-2-45" aria-label="Permalink to &quot;1.2.45&quot;">​</a></h2><ul><li>Fix only one reactor field working when multiple are active.</li><li>Fix float-spring rest condition.</li></ul><h2 id="_1-2-44" tabindex="-1">1.2.44 <a class="header-anchor" href="#_1-2-44" aria-label="Permalink to &quot;1.2.44&quot;">​</a></h2><ul><li>Revert an incorrect and unnecessary speculative &quot;fix&quot; for animation blend not being respected by rotational effects.</li></ul><h2 id="_1-2-43" tabindex="-1">1.2.43 <a class="header-anchor" href="#_1-2-43" aria-label="Permalink to &quot;1.2.43&quot;">​</a></h2><ul><li>Remove duplicate property sliders in the shared-params editor UI.</li><li>Replace usage of the array version of <code>Mathf.Min</code> / <code>Mathf.Max</code> with <code>VectorUtil.MinComponent</code> / <code>MaxComponent</code> to remove garbage allocation.</li></ul><h2 id="_1-2-42" tabindex="-1">1.2.42 <a class="header-anchor" href="#_1-2-42" aria-label="Permalink to &quot;1.2.42&quot;">​</a></h2><ul><li>Add options to lock rotational effects along specific axes (in either global or local space).</li></ul><h2 id="_1-2-41" tabindex="-1">1.2.41 <a class="header-anchor" href="#_1-2-41" aria-label="Permalink to &quot;1.2.41&quot;">​</a></h2><ul><li>Add assembly definitions.</li></ul><h2 id="_1-2-40" tabindex="-1">1.2.40 <a class="header-anchor" href="#_1-2-40" aria-label="Permalink to &quot;1.2.40&quot;">​</a></h2><ul><li>Fix null reference exception in <code>BoingBones.Reboot</code> when instantiated at specific timings.</li><li>Fix missing <code>override</code> keywords on <code>BoingEffector.OnEnable</code> / <code>OnDisable</code>.</li></ul><h2 id="_1-2-39" tabindex="-1">1.2.39 <a class="header-anchor" href="#_1-2-39" aria-label="Permalink to &quot;1.2.39&quot;">​</a></h2><ul><li>Fix invalid results pulled for objects not executed that frame (e.g. from late enabling or instantiation).</li><li>Fix unnecessary execution of disabled objects.</li><li>Fix incorrect rotation computation introduced in the previous update to respect animation blend.</li></ul><h2 id="_1-2-38" tabindex="-1">1.2.38 <a class="header-anchor" href="#_1-2-38" aria-label="Permalink to &quot;1.2.38&quot;">​</a></h2><ul><li>Fix animation blend not respected by rotational effects.</li><li>Remove garbage created by <code>VectorUtil.MinComponent</code> and <code>VectorUtil.MaxComponent</code>.</li></ul><h2 id="_1-2-37" tabindex="-1">1.2.37 <a class="header-anchor" href="#_1-2-37" aria-label="Permalink to &quot;1.2.37&quot;">​</a></h2><ul><li>Disable a broken attempt at altering <code>BoingBone.TwistPropagation</code> to match default values on older versions. Unity always calls <code>BoingBase.OnAfterDeserialize</code> with a revision of 0 the first time, which made the migration unreliable.</li></ul><h2 id="_1-2-36" tabindex="-1">1.2.36 <a class="header-anchor" href="#_1-2-36" aria-label="Permalink to &quot;1.2.36&quot;">​</a></h2><ul><li>Fix incorrect <code>FixedUpdate</code> implementation. <code>FixedUpdate</code> now updates with the rest of the game&#39;s <code>FixedUpdate</code> as expected.</li><li>Consolidate update mode and update timing into three update modes: <code>FixedUpdate</code>, <code>Early Update</code>, and <code>Late Update</code> (default). <ul><li><strong>Note:</strong> projects using older Boing Kit versions will need to re-adjust this property after updating.</li></ul></li><li>Remove additional calls to <code>GC.Alloc</code>.</li></ul><h2 id="_1-2-35" tabindex="-1">1.2.35 <a class="header-anchor" href="#_1-2-35" aria-label="Permalink to &quot;1.2.35&quot;">​</a></h2><ul><li>Fix Boing behaviors and reactors with non-unit scales being rebooted to unit scales.</li></ul><h2 id="_1-2-34" tabindex="-1">1.2.34 <a class="header-anchor" href="#_1-2-34" aria-label="Permalink to &quot;1.2.34&quot;">​</a></h2><ul><li>Add scale effects to Boing behaviors (off by default).</li><li>Fix changes to bone scales not being picked up by the Boing Bones component.</li><li>Fix null reference exceptions on the effector parameter list.</li></ul><h2 id="_1-2-33" tabindex="-1">1.2.33 <a class="header-anchor" href="#_1-2-33" aria-label="Permalink to &quot;1.2.33&quot;">​</a></h2><ul><li>Add <code>Twist Propagation</code> property to the Boing Bones component (defaulted to <code>true</code> for new creations; <code>false</code> for older creations, for backward compatibility).</li><li>Version tracking.</li></ul><h2 id="_1-2-32" tabindex="-1">1.2.32 <a class="header-anchor" href="#_1-2-32" aria-label="Permalink to &quot;1.2.32&quot;">​</a></h2><ul><li>Fix missing rotation propagation down bone chains.</li></ul><h2 id="_1-2-31" tabindex="-1">1.2.31 <a class="header-anchor" href="#_1-2-31" aria-label="Permalink to &quot;1.2.31&quot;">​</a></h2><ul><li>Smarter chain-rescan condition checks that take hierarchy changes into account.</li></ul><h2 id="_1-2-30" tabindex="-1">1.2.30 <a class="header-anchor" href="#_1-2-30" aria-label="Permalink to &quot;1.2.30&quot;">​</a></h2><ul><li>Fix false abortion of run-time chain rescan.</li><li>Fix mismatched delta time used for applying gravity to bones.</li></ul><h2 id="_1-2-29" tabindex="-1">1.2.29 <a class="header-anchor" href="#_1-2-29" aria-label="Permalink to &quot;1.2.29&quot;">​</a></h2><ul><li>Fix garbage collection caused by <code>Aabb.FromPoints</code>.</li><li>Fix garbage collection caused by <code>VectorUtil.ComponentWiseMult</code>.</li></ul><h2 id="_1-2-28" tabindex="-1">1.2.28 <a class="header-anchor" href="#_1-2-28" aria-label="Permalink to &quot;1.2.28&quot;">​</a></h2><ul><li>Fix garbage collection caused by <code>Bits32.IsBitSet</code>.</li></ul><h2 id="_1-2-27" tabindex="-1">1.2.27 <a class="header-anchor" href="#_1-2-27" aria-label="Permalink to &quot;1.2.27&quot;">​</a></h2><ul><li>Restore update timing. (Unity should really fix the timing of their sprite framework&#39;s transform read — it should happen after <code>LateUpdate()</code>, not after <code>Update()</code>.)</li><li>Fix one-frame-off error on non-loose root bones.</li></ul><h2 id="_1-2-26" tabindex="-1">1.2.26 <a class="header-anchor" href="#_1-2-26" aria-label="Permalink to &quot;1.2.26&quot;">​</a></h2><ul><li>Fix the reactor field compute shader for DirectX.</li><li>Fix time dependence of effector accumulation.</li></ul><h2 id="_1-2-25" tabindex="-1">1.2.25 <a class="header-anchor" href="#_1-2-25" aria-label="Permalink to &quot;1.2.25&quot;">​</a></h2><ul><li>Fix Inspector header text color in the dark theme.</li></ul><h2 id="_1-2-24" tabindex="-1">1.2.24 <a class="header-anchor" href="#_1-2-24" aria-label="Permalink to &quot;1.2.24&quot;">​</a></h2><ul><li>Remove the update-timing option — it was a crutch that introduced too much code complexity and a performance hit, all to accommodate issues in other external systems that improperly pull transform data too early for rendering.</li><li>Fix jitter in fixed-update mode.</li></ul><h2 id="_1-2-23" tabindex="-1">1.2.23 <a class="header-anchor" href="#_1-2-23" aria-label="Permalink to &quot;1.2.23&quot;">​</a></h2><ul><li>Add a shader subgraph, which can be used to create URP and HDRP shader graphs that sample reactor fields.</li></ul><h2 id="_1-2-22" tabindex="-1">1.2.22 <a class="header-anchor" href="#_1-2-22" aria-label="Permalink to &quot;1.2.22&quot;">​</a></h2><ul><li>Fix Boing Bones jitter in builds.</li></ul><h2 id="_1-2-21" tabindex="-1">1.2.21 <a class="header-anchor" href="#_1-2-21" aria-label="Permalink to &quot;1.2.21&quot;">​</a></h2><ul><li>Fix Boing Bones not restoring to original bone positions when disabled.</li><li>Fix objects being reset to the identity transform on synchronous scene reload.</li></ul><h2 id="_1-2-20" tabindex="-1">1.2.20 <a class="header-anchor" href="#_1-2-20" aria-label="Permalink to &quot;1.2.20&quot;">​</a></h2><ul><li>Fix exception when adding the Boing Bones component.</li><li>Fix bone exclusion from the Boing Bones component.</li></ul><h2 id="_1-2-19" tabindex="-1">1.2.19 <a class="header-anchor" href="#_1-2-19" aria-label="Permalink to &quot;1.2.19&quot;">​</a></h2><ul><li>Fix Boing behaviors and reactors having their rotation permanently changed without properly restoring when outside influence is gone.</li></ul><h2 id="_1-2-18" tabindex="-1">1.2.18 <a class="header-anchor" href="#_1-2-18" aria-label="Permalink to &quot;1.2.18&quot;">​</a></h2><ul><li>Fix editor errors when editing Boing reactor fields in the Inspector.</li><li>Fix inability to move objects with Boing behaviors in the editor under play mode.</li></ul><h2 id="_1-2-17" tabindex="-1">1.2.17 <a class="header-anchor" href="#_1-2-17" aria-label="Permalink to &quot;1.2.17&quot;">​</a></h2><ul><li>Use script execution order instead of camera-based events to apply and restore transforms. If this breaks interaction between Boing Kit and other procedural animation scripts, simply re-adjust their script execution order. Typically, Boing Kit&#39;s post-update pump needs to be last in the execution order list and the pre-update pump needs to be first.</li><li>Add update timing (Early vs Late) to Boing behaviors, Boing reactors, Boing reactor field CPU samplers, and Boing Bones. This option dictates when to apply transforms for rendering. <em>Late</em> is the original default, applying transforms at the end of <code>LateUpdate</code>. <em>Early</em> applies transforms at the end of <code>Update</code>, which accommodates scripts that unexpectedly pull transforms for rendering between <code>Update</code> and <code>LateUpdate</code> — such as Unity&#39;s skinned sprite renderer in certain versions.</li></ul><h2 id="_1-2-16" tabindex="-1">1.2.16 <a class="header-anchor" href="#_1-2-16" aria-label="Permalink to &quot;1.2.16&quot;">​</a></h2><ul><li>Add update mode (<code>Update</code> vs <code>FixedUpdate</code>) to Boing behaviors and Boing reactors. Use a matching update mode to other game logic to avoid jitter.</li><li>Add options to lock translational effects along specific axes (in either global or local space).</li></ul><h2 id="_1-2-15" tabindex="-1">1.2.15 <a class="header-anchor" href="#_1-2-15" aria-label="Permalink to &quot;1.2.15&quot;">​</a></h2><ul><li>Fix issues with gravity in fixed-update mode.</li></ul><h2 id="_1-2-14" tabindex="-1">1.2.14 <a class="header-anchor" href="#_1-2-14" aria-label="Permalink to &quot;1.2.14&quot;">​</a></h2><ul><li>Add update mode (<code>Update</code> vs <code>FixedUpdate</code>) to Boing Bones. Use a matching update mode to other game logic to avoid jitter.</li><li>Fix Boing Bones issues with switching and reloading scenes.</li><li>Fix bone transform drift over prolonged periods.</li></ul><h2 id="_1-2-13" tabindex="-1">1.2.13 <a class="header-anchor" href="#_1-2-13" aria-label="Permalink to &quot;1.2.13&quot;">​</a></h2><ul><li>Fix bones drifting further apart over time.</li></ul><h2 id="_1-2-12" tabindex="-1">1.2.12 <a class="header-anchor" href="#_1-2-12" aria-label="Permalink to &quot;1.2.12&quot;">​</a></h2><ul><li>Fix issues with multiple cameras in-game and multiple views in the editor.</li><li>Add README files with a new overview, quick-start guide, and instructions for setting up effects demonstrated in some examples.</li></ul><h2 id="_1-2-11" tabindex="-1">1.2.11 <a class="header-anchor" href="#_1-2-11" aria-label="Permalink to &quot;1.2.11&quot;">​</a></h2><ul><li>Fix namespace conflicts with the Oculus SDK in examples.</li></ul><h2 id="_1-2-10" tabindex="-1">1.2.10 <a class="header-anchor" href="#_1-2-10" aria-label="Permalink to &quot;1.2.10&quot;">​</a></h2><ul><li>Fix bad child rotation under bones with multiple children.</li></ul><h2 id="_1-2-9" tabindex="-1">1.2.9 <a class="header-anchor" href="#_1-2-9" aria-label="Permalink to &quot;1.2.9&quot;">​</a></h2><ul><li>Use a globally shared dummy collider for all Boing Bones.</li></ul><h2 id="_1-2-8" tabindex="-1">1.2.8 <a class="header-anchor" href="#_1-2-8" aria-label="Permalink to &quot;1.2.8&quot;">​</a></h2><ul><li>Fix crash when exceeding the initial effector count limit.</li></ul><h2 id="_1-2-7" tabindex="-1">1.2.7 <a class="header-anchor" href="#_1-2-7" aria-label="Permalink to &quot;1.2.7&quot;">​</a></h2><ul><li>Fix profiler error messages.</li></ul><h2 id="_1-2-6" tabindex="-1">1.2.6 <a class="header-anchor" href="#_1-2-6" aria-label="Permalink to &quot;1.2.6&quot;">​</a></h2><ul><li>Fix for multiple cameras. <ul><li><strong>Note:</strong> Due to technical limitations, effects appear in only one active Edit or Game view under Play Mode in the Unity editor (whichever gets rendered first). Effects show up normally on all cameras in built games.</li></ul></li></ul><h2 id="_1-2-5" tabindex="-1">1.2.5 <a class="header-anchor" href="#_1-2-5" aria-label="Permalink to &quot;1.2.5&quot;">​</a></h2><ul><li>SRP support (including LWRP and HDRP) for Unity 2019.1 or newer. <ul><li><strong>Note:</strong> Materials in the examples are still targeted for the built-in render pipeline. If using LWRP or HDRP, they need to be upgraded via <strong>Edit &gt; Render Pipeline</strong>. The example materials used alongside the reactor field&#39;s compute shader are modified from Unity&#39;s standard materials and cannot be automatically upgraded — try the examples under the built-in pipeline first.</li></ul></li></ul><h2 id="_1-2-4" tabindex="-1">1.2.4 <a class="header-anchor" href="#_1-2-4" aria-label="Permalink to &quot;1.2.4&quot;">​</a></h2><ul><li>Dynamic bouncy bones.</li></ul><h2 id="_1-1-3" tabindex="-1">1.1.3 <a class="header-anchor" href="#_1-1-3" aria-label="Permalink to &quot;1.1.3&quot;">​</a></h2><ul><li>Reactor field propagation.</li></ul><h2 id="_1-0-2" tabindex="-1">1.0.2 <a class="header-anchor" href="#_1-0-2" aria-label="Permalink to &quot;1.0.2&quot;">​</a></h2><ul><li>Registry callbacks.</li></ul><h2 id="_1-0-1" tabindex="-1">1.0.1 <a class="header-anchor" href="#_1-0-1" aria-label="Permalink to &quot;1.0.1&quot;">​</a></h2><ul><li>Fix for the custom shader example.</li></ul><h2 id="_1-0-0" tabindex="-1">1.0.0 <a class="header-anchor" href="#_1-0-0" aria-label="Permalink to &quot;1.0.0&quot;">​</a></h2><ul><li>Initial release.</li></ul>',99)])])}const p=a(l,[["render",r]]);export{m as __pageData,p as default};
